float map(vec3 p) { return length(p) - 1.0; }
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 ro = vec3(0.0, 0.0, -3.0), rd = normalize(vec3(p, 1.0));
    float t = 0.0;
    for (int i = 0; i < 128; i++) { float d = map(ro + rd * t); if (d < 0.001) break; t += d; }
    fragColor = vec4(vec3(1.0 / (1.0 + t * t * 0.1)), 1.0);
}
